const AUD_CT = { cli: "Client", fou: "Fournisseur", bq: "Banque", avo: "Avocat", aut: "Autre" }; const AUD_CST = [["", "À envoyer"], ["env", "Envoyée"], ["rel", "Relancée"], ["rec", "Reçue"], ["nr", "Non reçue · procédure alternative"]];
function audSoldeTiers(c, pref) { const by = {}; for (const e of c.L) for (const l of e.lignes) if (l.compte.startsWith(pref)) { const k = l.aux || l.compte; by[k] = (by[k] || 0) + l.debit - l.credit; } return by; }
