/* ---------------- anomalies ---------------- */
const AUD_AT = [["fact", "Factuelle"], ["jug", "De jugement"], ["extr", "Extrapolée"]];
function audAnomImp(x) { const mt = Number(x.mt) || 0; return (/^[67]/.test(x.cc || "") ? mt : 0) - (/^[67]/.test(x.cd || "") ? mt : 0); }
