/* ---------------- social et RH ---------------- */
VIEWS.audRhD = () => { const c = audCtx(); const A = AUD(); const R = A.rh; const s = (...p) => c.sp(...p), sp = (...p) => c.spp(...p); const eff = c.eff || 0;
  const rows = [["Salaires et traitements (641)", s("641"), sp("641")], ["dont primes et gratifications (6413)", s("6413"), sp("6413")], ["dont indemnités (6414)", s("6414"), sp("6414")], ["Rémunération du travail de l'exploitant (644)", s("644"), sp("644")], ["Charges sociales (645)", s("645"), sp("645")], ["Cotisations de l'exploitant (646)", s("646"), sp("646")], ["Autres charges sociales (647, 648)", s("647", "648"), sp("647", "648")], ["Personnel intérimaire (6211)", s("6211"), sp("6211")], ["Dettes sociales à la clôture (42, 43)", -s("42", "43"), -sp("42", "43")]];
  const tx = s("641") ? s("645") / s("641") * 100 : null; const moy = eff ? s("641") / eff : null; const smicAn = cnsRef().smic * 12 * 100;
  const al = []; if (tx != null && (tx < 20 || tx > 55)) al.push(["warn", "Taux de charges patronales de " + tx.toFixed(1).replace(".", ",") + " % : à analyser (allègements, erreurs d'imputation)."]); if (moy != null && moy < smicAn * 0.9) al.push(["warn", "Salaire moyen inférieur au SMIC annuel : vérifier l'effectif (temps partiels, entrées en cours d'année)."]); if (c.flags.E && !s("4282", "4382")) al.push(["warn", "Aucune provision pour congés payés."]); if (!c.flags.E) al.push(["ok", "Aucun salarié identifié : la plupart des contrôles sociaux sont sans objet."]);
  const th = [[1, "DPAE, registre du personnel, DUERP, mutuelle, entretiens professionnels"], [11, "Comité social et économique (CSE)"], [20, "Obligation d'emploi des travailleurs handicapés, contribution formation majorée"], [50, "Règlement intérieur, index égalité, participation, BDESE, CSE élargi"], [250, "Contribution supplémentaire à l'apprentissage, plan de mobilité"]];
  const f = (k, l) => `<label class="ecf-f"><span>${l}</span><input class="in num" value="${R[k] != null ? esc(String(R[k])) : ""}" data-ch="audRh" data-f="${k}"></label>`;
  return audHead("audRhD", "Données sociales issues de la comptabilité, comparées à N-1, ratios clés et obligations liées aux seuils d'effectif.") + audKpi([["Effectif retenu", String(eff)], ["Masse salariale", s("641", "644")], ["Taux de charges patronales", tx == null ? "—" : tx.toFixed(1).replace(".", ",") + " %"], ["Salaire moyen annuel", moy == null ? "—" : Math.round(moy)]]) +
    `<section class="card"><div class="card-h"><h3>Effectif</h3></div><div class="ecf-g">${f("eff", "Effectif moyen")}${f("effFin", "Effectif à la clôture")}${f("etp", "Équivalents temps plein")}${f("cdd", "Dont CDD et alternants")}</div></section>` +
    al.map(([k, t]) => `<div class="aud-auto ${k}" style="margin:0 0 8px"><span>${k === "ok" ? "✓" : "!"}</span>${esc(t)}</div>`).join("") +
    `<div class="grid g2"><section class="card"><div class="card-h"><h3>Charges de personnel</h3></div><div class="tw"><table class="t"><thead><tr><th></th><th class="r">${audY()}</th><th class="r">N-1</th><th class="r">Var.</th></tr></thead><tbody>${rows.map(([l, a, b]) => `<tr><td>${l}</td><td class="r mono">${audE(a)}</td><td class="r mono">${audE(b)}</td><td class="r mono">${b ? ((a - b) / Math.abs(b) * 100).toFixed(1).replace(".", ",") + " %" : "—"}</td></tr>`).join("")}</tbody></table></div></section>
    <section class="card"><div class="card-h"><h3>Obligations selon l'effectif</h3></div><div class="card-b">${th.map(([n, t]) => `<div class="aud-li ${eff >= n ? "" : "muted"}"><b>${eff >= n ? "✓" : "○"} À partir de ${n} salarié${n > 1 ? "s" : ""}</b><span class="small">${t}</span></div>`).join("")}</div></section></div>`; };
VIEWS.audRhP = () => { const c = audCtx(); const R = AUD().rh; const s = (...p) => c.sp(...p);
  const net = audMov(c, "421", "d"); const pas = audMov(c, "4421", "c"); const L = [["Salaire brut", s("641"), "dsnBrut"], ["Cotisations patronales", s("645"), "dsnPat"], ["Net payé aux salariés", net, "dsnNet"], ["Prélèvement à la source reversé", pas, "dsnPas"]];
  const rows = L.map(([l, cpt, k]) => { const d = R[k] != null && R[k] !== "" ? Number(R[k]) : null; return { l, cpt, k, d, e: d == null ? null : cpt - d }; }); const ec = rows.filter(r => r.e != null && Math.abs(r.e) > c.mat.sai);
  return audHead("audRhP", "Rapprochement des cumuls annuels de la paie (DSN, livre de paie) avec la comptabilité. Saisissez les cumuls déclarés : les écarts supérieurs au seuil des anomalies insignifiantes (" + audE(c.mat.sai) + ") sont signalés.") +
    audKpi([["Rubriques rapprochées", String(rows.filter(r => r.d != null).length) + " / " + rows.length], ["Écarts significatifs", String(ec.length), ec.length ? "neg" : "ok"], ["Dettes sociales à la clôture", -s("42", "43")], ["Charges sociales / salaires", s("641") ? (s("645") / s("641") * 100).toFixed(1).replace(".", ",") + " %" : "—"]]) +
    `<section class="card"><div class="tw"><table class="t aud-t"><thead><tr><th>Rubrique</th><th class="r">Comptabilité</th><th class="r">Paie / DSN (cumul annuel)</th><th class="r">Écart</th><th>Explication</th></tr></thead><tbody>${rows.map(r => `<tr class="${r.e != null && Math.abs(r.e) > c.mat.sai ? "aud-flag" : ""}"><td>${r.l}</td><td class="r mono">${audE(r.cpt)}</td><td class="r"><input class="in sm num" style="width:130px" value="${r.d != null ? toIn(r.d) : ""}" data-ch="audRhE" data-f="${r.k}"></td><td class="r mono ${r.e ? "neg" : ""}">${r.e == null ? "—" : audE(r.e)}</td><td><input class="in sm" style="width:100%" value="${esc(R[r.k + "X"] || "")}" data-ch="audRh" data-f="${r.k}X"></td></tr>`).join("")}</tbody></table></div></section>
    <section class="card"><div class="card-h"><h3>Dettes sociales à la clôture</h3></div><div class="tw"><table class="t"><tbody>${[["421", "Rémunérations dues"], ["431", "Sécurité sociale (Urssaf)"], ["437", "Autres organismes (retraite, prévoyance, mutuelle)"], ["4282", "Dettes provisionnées pour congés payés"], ["4382", "Charges sociales sur congés payés"], ["4421", "Prélèvement à la source"]].map(([p, l]) => `<tr><td class="mono">${p}</td><td>${l}</td><td class="r mono">${audE(-s(p))}</td></tr>`).join("")}</tbody></table></div><div class="card-b small muted">Vérifier le paiement de ces dettes après la clôture (relevés bancaires de janvier) et leur concordance avec la dernière DSN.</div></section>`; };
VIEWS.audRhC = () => audChkView("audRhC", "Conformité sociale adaptée à l'effectif (" + audCtx().eff + " salarié(s)) et au type d'entité : embauche, contrats, temps de travail, santé et sécurité, obligations liées aux seuils.");
VIEWS.audRhR = () => audChkView("audRhR", "Risques sociaux et contentieux : litiges, contrôles Urssaf, risques de requalification, engagements de retraite et vigilance sur la sous-traitance.");

/* ---------------- fiscal ---------------- */
VIEWS.audFiT = () => { const c = audCtx(); const F = AUD().fi; const ca = -c.sp("70") + c.sp("709"); const col = audMov(c, "4457", "c") - 0; const ded = audMov(c, "4456", "d"); const base = c.sp("60", "61", "62") + audMov(c, "2", "d");
  const tx = Number(F.tx || 20); const th = Math.round(ca * tx / 100); const decl = F.caDecl != null && F.caDecl !== "" ? Number(F.caDecl) : null; const e1 = decl == null ? null : ca - decl; const e2 = col - th;
  return audHead("audFiT", "Cadrage de la TVA : chiffre d'affaires comptable et TVA collectée, TVA déductible et base d'achats, rapprochement avec les déclarations déposées. Le détail période par période est disponible dans les cadrages du module Fiscalité.", `<button class="btn" data-act="audGo" data-v="tvaCad">Cadrages de TVA →</button>`) +
    (c.flags.TVA ? "" : `<div class="aud-auto ok" style="margin:0 0 12px"><span>✓</span>Entité en franchise en base de TVA : vérifier le respect des seuils de franchise.</div>`) +
    audKpi([["Chiffre d'affaires HT", ca], ["TVA collectée", col], ["Taux apparent", ca ? (col / ca * 100).toFixed(2).replace(".", ",") + " %" : "—"], ["TVA déductible", ded]]) +
    `<section class="card"><div class="tw"><table class="t aud-t"><thead><tr><th>Contrôle</th><th class="r">Comptabilité</th><th class="r">Référence</th><th class="r">Écart</th></tr></thead><tbody>
      <tr><td>Chiffre d'affaires comptable / chiffre d'affaires déclaré (cumul des CA3 ou CA12)</td><td class="r mono">${audE(ca)}</td><td class="r"><input class="in sm num" style="width:130px" value="${decl != null ? toIn(decl) : ""}" placeholder="à saisir" data-ch="audFi" data-f="caDecl" data-u="eur"></td><td class="r mono ${e1 && Math.abs(e1) > c.mat.sai ? "neg" : ""}">${e1 == null ? "—" : audE(e1)}</td></tr>
      <tr><td>TVA collectée / TVA théorique au taux de <input class="in sm num" style="width:60px" value="${tx}" data-ch="audFi" data-f="tx"> %</td><td class="r mono">${audE(col)}</td><td class="r mono">${audE(th)}</td><td class="r mono ${Math.abs(e2) > c.mat.sp ? "neg" : ""}">${audE(e2)}</td></tr>
      <tr><td>TVA déductible / base d'achats et d'immobilisations</td><td class="r mono">${audE(ded)}</td><td class="r mono">${audE(base)}</td><td class="r mono">${base ? (ded / base * 100).toFixed(1).replace(".", ",") + " %" : "—"}</td></tr>
      <tr><td>TVA à décaisser ou crédit de TVA à la clôture (4455, 44567)</td><td class="r mono">${audE(-c.sp("4455", "44567"))}</td><td></td><td></td></tr></tbody></table></div></section>
    <section class="card aud-grp"><div class="card-h"><h3>Contrôles</h3></div>${audRow("ft1", "Écarts entre chiffre d'affaires comptable et déclaré expliqués (avoirs, encaissements, opérations exonérées)", "", "", c)}${audRow("ft2", "Taux de TVA appliqués conformes à la nature des opérations", "", "", c)}${audRow("ft3", "TVA non récupérable correctement exclue (véhicules de tourisme, cadeaux, hébergement)", "CGI ann. II 206", "", c)}${audRow("ft4", "Autoliquidations (intracommunautaire, sous-traitance BTP, importations) déclarées", "", "", c)}</section>`; };
VIEWS.audFiI = () => { const c = audCtx(); const s = (...p) => c.sp(...p); let r = null; try { r = calcIS(c.ex); } catch (e) { }
  const R = [["6712", "Pénalités, amendes fiscales et pénales", "Non déductibles (CGI 39-2)"], ["6713", "Dons et libéralités", "Réintégrés, réduction d'impôt mécénat éventuelle"], ["6234", "Cadeaux à la clientèle", "Déductibles si justifiés ; déclaration au-delà de 3 000 € par an"], ["6257", "Réceptions", "À justifier (intérêt de l'entreprise)"], ["6351", "Impôts directs", "Vérifier la taxe annuelle sur les véhicules (non déductible)"], ["671", "Charges exceptionnelles sur opérations de gestion", "À analyser"], ["695", "Impôt sur les sociétés", "Réintégré"], ["6811", "Dotations aux amortissements", "Amortissements excédentaires des véhicules à réintégrer (CGI 39-4)"]].map(([p, l, n]) => ({ p, l, n, v: s(p) })).filter(x => x.v);
  return audHead("audFiI", "Passage du résultat comptable au résultat fiscal : charges non déductibles, réintégrations et déductions, calcul de l'IS et acomptes versés. Le détail est dans le module Fiscalité › Résultat fiscal.", `<button class="btn" data-act="audGo" data-v="is">Résultat fiscal →</button>`) +
    audKpi([["Résultat comptable avant IS", c.D.rcai], ["Résultat fiscal calculé", r ? r.rf : "—"], ["IS calculé", r ? r.is : "—"], ["IS comptabilisé (695)", s("695")]]) +
    `<section class="card"><div class="card-h"><h3>Comptes à analyser</h3></div><div class="tw"><table class="t"><thead><tr><th>Compte</th><th>Nature</th><th class="r">Montant</th><th>Traitement fiscal</th></tr></thead><tbody>${R.map(x => `<tr><td class="mono">${x.p}</td><td>${x.l}</td><td class="r mono">${audE(x.v)}</td><td class="small">${x.n}</td></tr>`).join("") || '<tr><td colspan="4" class="muted">Aucun compte sensible mouvementé.</td></tr>'}</tbody></table></div></section>
    <section class="card aud-grp"><div class="card-h"><h3>Contrôles</h3></div>${audRow("fi1", "Écart entre IS calculé et IS comptabilisé analysé", r && Math.abs((r.is || 0) - s("695")) > c.mat.sai ? "Écart de " + audE((r.is || 0) - s("695")) : "", "", c)}${audRow("fi2", "Réintégrations et déductions extra-comptables justifiées (2058-A / 2033-B)", "", "", c)}${audRow("fi3", "Déficits reportables suivis et correctement imputés", "CGI 209-I", "", c)}${audRow("fi4", "Taux réduit d'IS applicable (capital libéré, détenu à 75 % par des personnes physiques, CA < 10 M€)", "CGI 219-I-b", "", c)}${audRow("fi5", "Acomptes d'IS et contribution sociale versés aux échéances", "", "isDeadl", c)}</section>`; };
VIEWS.audFiA = () => { const c = audCtx(); const by = {}; for (const k in c.m) if (/^63/.test(k)) by[k] = [c.m[k], 0]; for (const k in c.mp) if (/^63/.test(k)) (by[k] ||= [0, 0])[1] = c.mp[k]; const L = Object.entries(by).sort();
  const exp = []; if (["tpe", "pme", "independant", "createur"].includes(c.act) && !c.sp("63511") && c.pv) exp.push("Aucune cotisation foncière des entreprises (63511) : exonération à justifier ou charge omise."); if (c.flags.E && !c.sp("6312", "6313", "6333")) exp.push("Aucune contribution formation ou taxe d'apprentissage alors que l'entité emploie du personnel."); if (c.act === "sci" && !c.sp("63512")) exp.push("Aucune taxe foncière (63512) pour une SCI détenant des immeubles.");
  return audHead("audFiA", "Revue des impôts et taxes (CFE, CVAE, taxes foncières, taxes assises sur les salaires, taxes sur les véhicules) et des taxes attendues selon le profil de l'entité.") +
    exp.map(t => `<div class="aud-auto warn" style="margin:0 0 8px"><span>!</span>${esc(t)}</div>`).join("") +
    `<section class="card"><div class="tw"><table class="t"><thead><tr><th>Compte</th><th>Libellé</th><th class="r">${audY()}</th><th class="r">N-1</th><th class="r">Var.</th></tr></thead><tbody>${L.map(([k, [a, b]]) => `<tr><td class="mono">${k}</td><td>${esc(accLib(k) || "")}</td><td class="r mono">${audE(a)}</td><td class="r mono">${audE(b)}</td><td class="r mono">${audE(a - b)}</td></tr>`).join("") || '<tr><td colspan="5" class="muted">Aucun impôt ni taxe comptabilisé.</td></tr>'}</tbody></table></div></section>
    <section class="card aud-grp"><div class="card-h"><h3>Contrôles</h3></div>${audRow("fa1", "Base de la CFE rapprochée de l'avis d'imposition et des locaux occupés", "", "", c)}${audRow("fa2", "CVAE : assujettissement et dégrèvement examinés (CA > 500 000 €)", "", "", c)}${audRow("fa3", "Taxes sur les salaires, apprentissage et formation calculées sur la masse salariale", "", "", c)}${audRow("fa4", "Taxes annuelles sur les véhicules de tourisme déclarées", "CGI 1010", "", c)}</section>`; };
VIEWS.audFiC = () => audChkView("audFiC", "Obligations déclaratives et règles fiscales, adaptées au régime et au type d'entité (société, association, SCI, entrepreneur individuel).");

/* ---------------- juridique ---------------- */
VIEWS.audJuS = () => { const c = audCtx(); const top = `<section class="card"><div class="card-h"><h3>Indicateurs</h3></div><div class="tw"><table class="t"><tbody><tr><td>Capitaux propres / capital social</td><td class="r mono">${audE(c.D.cp)} / ${audE(c.D.capital)}</td><td class="r">${c.D.capital ? (c.D.cp >= c.D.capital / 2 ? audPill("Conforme", "#059669") : audPill("Inférieurs à la moitié", "#DC2626")) : "—"}</td></tr><tr><td>Total du bilan (seuil CAC : 5 M€)</td><td class="r mono">${audE(c.D.tb)}</td><td class="r">${c.D.tb > 500000000 ? audPill("Dépassé", "#D97706") : "—"}</td></tr><tr><td>Chiffre d'affaires HT (seuil CAC : 10 M€)</td><td class="r mono">${audE(c.D.ca)}</td><td class="r">${c.D.ca > 1000000000 ? audPill("Dépassé", "#D97706") : "—"}</td></tr><tr><td>Effectif (seuil CAC : 50)</td><td class="r mono">${c.eff}</td><td class="r">${c.eff > 50 ? audPill("Dépassé", "#D97706") : "—"}</td></tr></tbody></table></div></section>`;
  return audChkView("audJuS", "Vie sociale, gouvernance et obligations légales de l'entité, adaptées à sa forme (société, association, entrepreneur individuel, SCI).", top); };
VIEWS.audJuC = () => audChkView("audJuC", "Contrats, engagements hors bilan, assurances, litiges et délais de paiement.");

/* ---------------- contrôle interne ---------------- */
function audProcs(c) { return Object.keys(AUD_CIQ).filter(k => audFor(AUD_PROC_TAGS[k], c)); }
function audCiScore(k, c) { const Q = AUD_CIQ[k][1].filter(x => audFor(x[1], c)); const A = AUD().ciq; const ans = Q.filter(x => A[x[0]] && A[x[0]] !== "na"); const oui = ans.filter(x => A[x[0]] === "oui").length; return { n: Q.length, rep: Q.filter(x => A[x[0]]).length, pct: ans.length ? Math.round(oui / ans.length * 100) : null }; }
VIEWS.audCiQ = () => { const c = audCtx(); const P = audProcs(c); const st = UI.sub.aud ||= {}; const cur = P.includes(st.proc) ? st.proc : P[0]; const A = AUD().ciq; const sc = k => audCiScore(k, c);
  return audHead("audCiQ", "Questionnaires de contrôle interne par processus : chaque « Non » signale une faiblesse et alimente automatiquement les recommandations.") +
    `<div class="aud-cyc">${P.map(k => { const s = sc(k); return `<button class="${k === cur ? "on" : ""}" data-act="audProc" data-k="${k}"><span>${esc(AUD_CIQ[k][0])}</span><i style="--p:${s.pct ?? 0}%"></i><small>${s.rep}/${s.n} · ${s.pct == null ? "—" : s.pct + " % maîtrisé"}</small></button>`; }).join("")}</div>` +
    (cur ? `<section class="card aud-grp"><div class="card-h"><h3>${esc(AUD_CIQ[cur][0])}</h3></div>${AUD_CIQ[cur][1].filter(x => audFor(x[1], c)).map(([id, , q, reco]) => `<div class="aud-row"><div class="aud-row-m"><div class="aud-row-t">${esc(q)}</div>${A[id] === "non" ? `<div class="aud-auto warn"><span>!</span>Recommandation : ${esc(reco)}</div>` : ""}<textarea class="in sm aud-obs" rows="1" placeholder="Description du contrôle, personne responsable, preuve…" data-ch="audIt" data-id="${id}" data-f="obs">${esc((AUD().it[id] || {}).obs || "")}</textarea></div><div class="aud-row-s"><div class="seg">${[["oui", "Oui"], ["non", "Non"], ["na", "N/A"]].map(([k, l]) => `<button class="${A[id] === k ? "on" : ""}" data-act="audCiA" data-id="${id}" data-v="${k}">${l}</button>`).join("")}</div><div class="aud-sigs">${audSig(AUD().it[id], "p", id)}${audSig(AUD().it[id], "r", id)}${audNoteBtn(id)}</div></div></div>`).join("")}</section>` : ""); };
VIEWS.audCiM = () => { const c = audCtx(); const P = audProcs(c); const R = AUD().rcm; const all = P.flatMap(k => (AUD_RCM[k] || []).map(x => [k].concat(x))); const tst = all.filter(x => (R[x[1]] || {}).res).length; const def = all.filter(x => (R[x[1]] || {}).res === "def").length;
  return audHead("audCiM", "Matrice des risques et contrôles clés : description du contrôle, test de cheminement et d'efficacité, conclusion. Une déficience alimente les recommandations.") + audKpi([["Contrôles clés", String(all.length)], ["Testés", tst + " / " + all.length], ["Déficiences", String(def), def ? "neg" : "ok"], ["Processus couverts", String(P.length)]]) +
    `<section class="card"><div class="tw"><table class="t aud-t"><thead><tr><th>Processus</th><th>Risque</th><th>Contrôle clé</th><th>Type</th><th>Fréquence / responsable</th><th>Test réalisé</th><th>Conclusion</th></tr></thead><tbody>${all.map(([k, id, risk, ctl, typ]) => { const x = R[id] || {}; return `<tr><td class="small">${esc(AUD_CIQ[k][0])}</td><td><b>${esc(risk)}</b></td><td><input class="in sm" style="width:100%;min-width:200px" value="${esc(x.ctl != null ? x.ctl : ctl)}" data-ch="audRcm" data-id="${id}" data-f="ctl"></td><td class="small">${esc(typ)}</td><td><input class="in sm" style="width:140px" value="${esc(x.freq || "")}" placeholder="Mensuel · DAF" data-ch="audRcm" data-id="${id}" data-f="freq"></td><td><input class="in sm" style="width:100%;min-width:160px" value="${esc(x.test || "")}" placeholder="Cheminement, 25 contrôles testés…" data-ch="audRcm" data-id="${id}" data-f="test"></td><td><select class="in sm" data-ch="audRcm" data-id="${id}" data-f="res"><option value="">Non testé</option><option value="eff" ${x.res === "eff" ? "selected" : ""}>Efficace</option><option value="def" ${x.res === "def" ? "selected" : ""}>Déficience</option><option value="na" ${x.res === "na" ? "selected" : ""}>Absent</option></select></td></tr>`; }).join("")}</tbody></table></div></section>`; };
function audRecos() { const c = audCtx(); const A = AUD(); const out = [];
  audProcs(c).forEach(k => AUD_CIQ[k][1].forEach(([id, t, q, reco]) => { if (audFor(t, c) && A.ciq[id] === "non") out.push({ id: "q:" + id, proc: AUD_CIQ[k][0], constat: q.replace(/ \?$/, "") + " : non", reco, auto: true }); }));
  audProcs(c).forEach(k => (AUD_RCM[k] || []).forEach(([id, risk, ctl]) => { const x = A.rcm[id] || {}; if (x.res === "def" || x.res === "na") out.push({ id: "m:" + id, proc: AUD_CIQ[k][0], constat: "Contrôle « " + (x.ctl || ctl) + " » " + (x.res === "def" ? "inefficace" : "absent") + " (risque : " + risk.toLowerCase() + ")", reco: "Mettre en place et documenter le contrôle : " + (x.ctl || ctl) + ".", auto: true }); }));
  Object.entries(AUD_CHK).forEach(([v, G]) => G.forEach(([g, items]) => items.forEach(([id, t, txt]) => { if (audFor(t, c) && (A.it[id] || {}).st === "an") out.push({ id: "c:" + id, proc: AUD_VL[v] || v, constat: txt + ((A.it[id] || {}).obs ? " — " + A.it[id].obs : ""), reco: "Régulariser le point relevé.", auto: true }); })));
  return out.concat(A.reco.map(x => Object.assign({ perso: true }, x))).map(x => Object.assign(x, (A.reco.find(r => r.id === x.id) || {}), { meta: (A.recoM || {})[x.id] || {} })); }
VIEWS.audCiR = () => { const L = audRecos(); const A = AUD(); A.recoM ||= {}; const PR = [["1", "Élevée"], ["2", "Moyenne"], ["3", "Faible"]];
  return audHead("audCiR", "Recommandations issues des questionnaires, de la matrice des contrôles et des points relevés dans les check-lists, avec la réponse de la direction. Elles alimentent la lettre de recommandations.", `<button class="btn" data-act="audRecoAdd">+ Recommandation</button><button class="btn pri" data-act="audDocGo" data-k="mgmt">Lettre de recommandations</button>`) +
    audKpi([["Recommandations", String(L.length)], ["Priorité élevée", String(L.filter(x => (x.meta.prio || "2") === "1").length)], ["Acceptées par la direction", String(L.filter(x => x.meta.st === "acc").length)], ["Mises en œuvre", String(L.filter(x => x.meta.st === "fait").length), "ok"]]) +
    `<section class="card"><div class="tw"><table class="t aud-t"><thead><tr><th>Domaine</th><th>Constat</th><th>Recommandation</th><th>Priorité</th><th>Réponse de la direction</th><th>Responsable / échéance</th><th>Suivi</th></tr></thead><tbody>${L.map(x => { const m = x.meta; return `<tr><td class="small">${esc(x.proc || "")}</td><td>${x.perso ? `<input class="in sm" style="width:100%;min-width:180px" value="${esc(x.constat || "")}" data-ch="audRecoP" data-id="${x.id}" data-f="constat">` : esc(x.constat)}</td><td>${x.perso ? `<input class="in sm" style="width:100%;min-width:180px" value="${esc(x.reco || "")}" data-ch="audRecoP" data-id="${x.id}" data-f="reco">` : esc(x.reco)}</td><td><select class="in sm" data-ch="audRecoM" data-id="${x.id}" data-f="prio">${PR.map(([k, l]) => `<option value="${k}" ${(m.prio || "2") === k ? "selected" : ""}>${l}</option>`).join("")}</select></td><td><input class="in sm" style="width:100%;min-width:160px" value="${esc(m.rep || "")}" data-ch="audRecoM" data-id="${x.id}" data-f="rep"></td><td><input class="in sm" style="width:110px" value="${esc(m.resp || "")}" placeholder="Qui ?" data-ch="audRecoM" data-id="${x.id}" data-f="resp"> <input type="date" class="in sm" value="${esc(m.ech || "")}" data-ch="audRecoM" data-id="${x.id}" data-f="ech"></td><td><select class="in sm" data-ch="audRecoM" data-id="${x.id}" data-f="st"><option value="">Ouverte</option><option value="acc" ${m.st === "acc" ? "selected" : ""}>Acceptée</option><option value="fait" ${m.st === "fait" ? "selected" : ""}>Mise en œuvre</option><option value="ref" ${m.st === "ref" ? "selected" : ""}>Refusée</option></select>${x.perso ? `<button class="btn sm ghost" data-act="audRecoDel" data-id="${x.id}">✕</button>` : ""}</td></tr>`; }).join("") || `<tr><td colspan="7" class="muted">Aucune recommandation : répondez aux questionnaires de contrôle interne.</td></tr>`}</tbody></table></div></section>`; };

/* ---------------- systèmes d'information ---------------- */
VIEWS.audSiG = () => audChkView("audSiG", "Contrôles généraux informatiques (ITGC) : gestion des accès, séparation des droits, sauvegardes, sécurité, changements et prestataires.");
VIEWS.audSiD = () => audChkView("audSiD", "Conformité des données : FEC, logiciel de caisse, archivage probant, facturation électronique, RGPD et prévention des fraudes.");

/* ---------------- notes de revue ---------------- */
function audRefLib(ref) { if (!ref) return ""; if (ref.startsWith("wp:")) return "Feuille : " + (AUD_VL[ref.slice(3)] || ref.slice(3)); if (ref.startsWith("ana:")) return "Revue analytique · compte " + ref.slice(4);
  for (const G of Object.values(AUD_CHK)) for (const [, items] of G) { const x = items.find(i => i[0] === ref); if (x) return x[2].slice(0, 60); } for (const L of Object.values(AUD_PRG)) { const x = L.find(i => i[0] === ref); if (x) return x[2].slice(0, 60); } return ref; }
VIEWS.audNotes = () => { const A = AUD(); const st = UI.sub.aud ||= {}; const f = st.nf || "open"; const L = A.notes.filter(n => f === "all" || (f === "open" ? n.st !== "clos" : n.st === "clos"));
  return audHead("audNotes", "Notes de revue posées par le réviseur sur les feuilles de travail et les contrôles : réponse du préparateur, puis clôture par le réviseur.", `<button class="btn" data-act="audNote" data-ref="wp:audHub">+ Note générale</button>`) +
    audKpi([["Notes", String(A.notes.length)], ["Ouvertes", String(A.notes.filter(n => !n.st).length), A.notes.some(n => !n.st) ? "neg" : ""], ["Répondues", String(A.notes.filter(n => n.st === "rep").length)], ["Clôturées", String(A.notes.filter(n => n.st === "clos").length), "ok"]]) +
    `<div class="seg" style="margin-bottom:10px">${[["open", "À traiter"], ["clos", "Clôturées"], ["all", "Toutes"]].map(([k, l]) => `<button class="${f === k ? "on" : ""}" data-act="audNf" data-v="${k}">${l}</button>`).join("")}</div>
    <section class="card">${L.map(n => { const i = A.notes.indexOf(n); return `<div class="id-row"><div class="id-main"><div class="id-top"><b>${esc(n.txt)}</b>${n.st === "clos" ? audPill("Clôturée", "#059669") : n.st === "rep" ? audPill("Répondue", "#2563EB") : audPill("Ouverte", "#DC2626")}</div><div class="small muted">${esc(audRefLib(n.ref))} · ${esc(n.by)} · ${frDate(n.le)}</div>
      <div class="row" style="gap:8px;margin-top:6px"><input class="in sm" style="flex:1" value="${esc(n.rep || "")}" placeholder="Réponse du préparateur…" data-ch="audNoteR" data-i="${i}">${n.st !== "clos" ? `<button class="btn sm" data-act="audNoteC" data-i="${i}">Clôturer</button>` : `<button class="btn sm ghost" data-act="audNoteO" data-i="${i}">Rouvrir</button>`}${n.ref && n.ref.startsWith("wp:") ? `<button class="btn sm ghost" data-act="audGo" data-v="${n.ref.slice(3)}">Ouvrir →</button>` : ""}<button class="btn sm ghost" data-act="audNoteD" data-i="${i}">✕</button></div></div></div>`; }).join("") || `<div class="card-b muted">Aucune note.</div>`}</section>`; };

/* le contexte d'audit est recalculé à chaque affichage */
const _audRN = renderNow; renderNow = function () { _audCtxK = null; return _audRN.apply(this, arguments); };
